package com.indiesoundquest.conversation.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="conversation") public class Conversation {
 @Id private UUID id; @Column(name="guest_session_id",nullable=false) private UUID guestSessionId; @Column(nullable=false,length=120) private String title; @Column(columnDefinition="LONGTEXT") private String summary; @Column(name="summary_version",nullable=false) private int summaryVersion; @Column(name="summary_through_sequence",nullable=false) private long summaryThroughSequence; @Column(name="summary_updated_at") private Instant summaryUpdatedAt; @Enumerated(EnumType.STRING) @Column(nullable=false) private ConversationStatus status; @Column(name="last_message_at",nullable=false) private Instant lastMessageAt; @Column(name="created_at",nullable=false) private Instant createdAt; @Column(name="updated_at",nullable=false) private Instant updatedAt;
 protected Conversation(){} public Conversation(UUID id,UUID guestSessionId,String title){this.id=id;this.guestSessionId=guestSessionId;this.title=title;status=ConversationStatus.ACTIVE;summaryVersion=0;summaryThroughSequence=0;createdAt=updatedAt=lastMessageAt=Instant.now();} public UUID getId(){return id;} public UUID getGuestSessionId(){return guestSessionId;} public String getTitle(){return title;} public String getSummary(){return summary;} public int getSummaryVersion(){return summaryVersion;} public long getSummaryThroughSequence(){return summaryThroughSequence;} public Instant getSummaryUpdatedAt(){return summaryUpdatedAt;} public ConversationStatus getStatus(){return status;} public Instant getLastMessageAt(){return lastMessageAt;} public void rename(String value){title=value;updatedAt=Instant.now();} public void archive(){status=ConversationStatus.ARCHIVED;updatedAt=Instant.now();} public void restore(){status=ConversationStatus.ACTIVE;updatedAt=Instant.now();} public void delete(){status=ConversationStatus.DELETED;updatedAt=Instant.now();} public void touch(){lastMessageAt=updatedAt=Instant.now();} public void updateSummary(String value,long throughSequence){if(throughSequence<=summaryThroughSequence)return;summary=value;summaryThroughSequence=throughSequence;summaryVersion+=1;summaryUpdatedAt=updatedAt=Instant.now();}
}
